from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple
import numpy as np

# --- Data structures ---
@dataclass
class RealTimeMetrics:
    typing_speed: float          # chars per second (baseline = 10.0)
    voice_pitch: float           # relative pitch (0.0–1.0, higher = stressed/upset)
    sentiment_score: float       # -1.0 (negative) to +1.0 (positive)

@dataclass
class HistoricalData:
    avg_typing_speed: float
    avg_sentiment: float
    frustration_threshold: float
    boredom_threshold: float
    preferred_intervention: str  # e.g., "micro_commitment", "reframe_goal", "celebration"
    skill_decay_curve: List[float]  # recent mastery scores

@dataclass
class Intervention:
    type: str                   # "reframe_goal", "micro_commitment", "celebration", "break_nudge"
    message: str
    payload: Optional[Dict] = None   # e.g., {"commitment_size": 3, "topic": "derivatives"}

# --- Core function ---
def trigger_emotional_intervention(
    user_id: str,
    real_time_metrics: RealTimeMetrics,
    historical_data: HistoricalData
) -> Intervention:
    """
    Decide which intervention to deploy based on real-time emotional state
    and historical learning profile.
    """

    # 1. Derive emotional state from real‑time metrics
    state = _classify_emotional_state(real_time_metrics, historical_data)

    # 2. Retrieve user’s current goal proximity & upcoming milestone
    goal_context = _get_goal_context(user_id, historical_data)

    # 3. Select intervention based on state + goal context
    if state == "frustrated":
        # Frustration → reframe the current goal to a smaller, achievable chunk
        return Inter-vention(
            type="reframe_goal",
            message=f"Let's break this down. You're {goal_context.progress_pct}% through the current module. How about we focus on just the next 3 practice problems?",
            payload={"new_milestone": "3_problems", "original_goal": goal_context.current_goal}
        )

    elif state == "bored":
        # Boredom → introduce a micro‑commitment that connects to a personal interest
        interest = _get_next_interest_hook(user_id, historical_data)
        return Intervention(
            type="micro_commitment",
            message=f"I noticed you're cruising. Want to try a quick challenge? {interest['hint']} (takes ~2 min)",
            payload={"commitment_type": "challenge", "topic": interest["topic"], "duration": 2}
        )

    elif state == "disengaged" or state == "tired":
        # Disengagement/tiredness → offer a celebration of past progress + a small nudge to resume later
        recent_win = _get_recent_win(user_id, historical_data)
        return Intervention(
            type="break_nudge",
            message=f"Great work earlier – you mastered {recent_win.skill_name}! Want to take a 5‑min break, or try one tiny question to keep the streak alive?",
            payload={"options": ["break_5min", "micro_question"]}
        )

    elif state == "positive":
        # Positive sentiment → anticipate completion and offer an advanced micro‑commitment
        next_milestone = _predict_next_milestone(user_id, historical_data)
        return Intervention(
            type="celebration",
            message=f"You're on track to finish this unit {next_milestone.days_early} days early. Ready for a sneak peek at the next topic?",
            payload={"early_completion_bonus": next_milestone.bonus_exercise}
        )

    else:
        # Default: maintain flow with a subtle micro‑commitment
        return Intervention(
            type="micro_commitment",
            message="One step at a time. Ready for the next question?",
            payload={"auto_advance": True}
        )

# --- Helper functions (pseudocode) ---
def _classify_emotional_state(
    metrics: RealTimeMetrics,
    hist: HistoricalData
) -> str:
    """Classify current emotional state using thresholds from historical data."""
    deviation_typing = abs(metrics.typing_speed - hist.avg_typing_speed) / hist.avg_typing_speed
    stress_indicator = metrics.voice_pitch > 0.7 or deviation_typing > 0.3

    if stress_indicator and metrics.sentiment_score < hist.frustration_threshold:
        return "frustrated"
    if metrics.sentiment_score > 0.6 and deviation_typing < 0.1:
        return "bored"          # too easy or repetitive
    if metrics.sentiment_score < -0.5 and not stress_indicator:
        return "disengaged"
    if metrics.sentiment_score > 0.3 and metrics.typing_speed > hist.avg_typing_speed * 1.2:
        return "positive"
    return "neutral"

